#!/usr/bin/env python3
import json
from pathlib import Path
from xml.etree import ElementTree as ET

root=Path('.')
terms_path=root/'data/terms.json'; prov_path=root/'data/provenance.json'; sitemap_path=root/'sitemap.xml'
terms=json.loads(terms_path.read_text()); prov=json.loads(prov_path.read_text())
new_terms=[
{"term":"DeepSeek","slug":"deepseek","pronunciation":"deep seek","definition":"A Chinese artificial intelligence research organization that develops and publishes the DeepSeek family of language and reasoning models and operates DeepSeek web, app, and API services.","example":"DeepSeek publishes named model lines while also using the DeepSeek name for its consumer-facing AI service.","categories":["AI Organizations, Products & Models"],"aliases":["DeepSeek AI"],"status":"Established","partOfSpeech":"proper noun","entryType":"organization","added":"2026-08-29","lastReviewed":"2026-08-29","sources":[]},
{"term":"DeepSeek-R1","slug":"deepseek-r1","pronunciation":"deep seek R-one","definition":"A reasoning-model family from DeepSeek introduced around reinforcement-learning-based reasoning, including DeepSeek-R1, DeepSeek-R1-Zero, and related distilled models.","example":"DeepSeek-R1 became a widely discussed example of a reasoning-focused model family.","categories":["AI Organizations, Products & Models","AI Systems & Technical Concepts"],"aliases":["R1"],"status":"Established","partOfSpeech":"proper noun","entryType":"model-family","added":"2026-08-29","lastReviewed":"2026-08-29","sources":[]}
]
for t in new_terms:
    if any(x['slug']==t['slug'] for x in terms): raise SystemExit(f"duplicate {t['slug']}")
terms.extend(new_terms); terms.sort(key=lambda x:x['term'].lower())
prov['deepseek']={"researchStatus":"researched","origin":"DeepSeek is the English-facing name used by Hangzhou DeepSeek Artificial Intelligence Co., Ltd. for its AI research organization, models, and consumer/developer services. Because the same brand name spans the organization and its web/app experience, EpochLex uses one organization entry rather than creating two indistinguishable entries titled DeepSeek.","firstKnownUse":None,"history":[{"date":"2026-04-24","event":"DeepSeek released DeepSeek-V4, continuing its use of specific versioned model names alongside the broader DeepSeek organization and service brand."}],"relatedTerms":["deepseek-r1","reasoning-model","large-language-model"],"sources":[{"id":"deepseek-model-disclosure-2026","type":"primary","publisher":"DeepSeek","title":"Model Mechanism and Training Methods of DeepSeek","published":None,"url":"https://cdn.deepseek.com/policies/en-US/model-algorithm-disclosure.html","supports":["definition","identity","usage"]},{"id":"deepseek-official-site-2026","type":"primary","publisher":"DeepSeek","title":"DeepSeek | Into the Unknown","published":None,"url":"https://www.deepseek.com/en/","supports":["definition","product context","usage"]},{"id":"deepseek-transparency-2026","type":"primary","publisher":"DeepSeek","title":"DeepSeek Transparency Center","published":None,"url":"https://www.deepseek.com/en/transparency/","supports":["history","model naming"]}]}
prov['deepseek-r1']={"researchStatus":"researched","origin":"DeepSeek introduced DeepSeek-R1 as a reasoning-focused model line trained to develop reasoning behavior through reinforcement learning. Official materials distinguish DeepSeek-R1 and DeepSeek-R1-Zero and also publish multiple R1-distilled models, supporting treatment of R1 as a model family rather than a single immutable version.","firstKnownUse":{"date":"2025-01-20","precision":"day","note":"DeepSeek announced DeepSeek-R1 and published its official model materials in January 2025."},"history":[{"date":"2025-01-20","event":"DeepSeek released DeepSeek-R1 and DeepSeek-R1-Zero with accompanying model documentation."}],"relatedTerms":["deepseek","reasoning-model","distillation","reinforcement-learning"],"sources":[{"id":"deepseek-r1-repo","type":"primary","publisher":"DeepSeek","title":"DeepSeek-R1","published":"2025-01-20","url":"https://github.com/deepseek-ai/DeepSeek-R1","supports":["definition","origin","history","model family"]},{"id":"deepseek-transparency-2026","type":"primary","publisher":"DeepSeek","title":"DeepSeek Transparency Center","published":None,"url":"https://www.deepseek.com/en/transparency/","supports":["history","model naming"]}]}
terms_path.write_text(json.dumps(terms,separators=(',',':'),ensure_ascii=False)+'\n')
prov_path.write_text(json.dumps(prov,indent=2,ensure_ascii=False)+'\n')

def page(t):
 d=t['definition']; n=t['term']; slug=t['slug']; p=t['pronunciation']
 import html, json as j
 esc=html.escape
 ld=j.dumps({"@context":"https://schema.org","@type":"DefinedTerm","name":n,"description":d,"url":f"https://jeffthomasiii.github.io/dictionary-of-the-ai-era/terms/{slug}/","inDefinedTermSet":"https://jeffthomasiii.github.io/dictionary-of-the-ai-era/","inLanguage":"en"},ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
 return f'''<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="color-scheme" content="light dark">\n  <title>{esc(n)} | EpochLex</title>\n  <meta name="description" content="{esc(d,quote=True)}">\n  <link rel="canonical" href="https://jeffthomasiii.github.io/dictionary-of-the-ai-era/terms/{slug}/">\n  <meta property="og:site_name" content="EpochLex">\n  <meta property="og:title" content="{esc(n)} | EpochLex">\n  <meta property="og:description" content="{esc(d,quote=True)}">\n  <meta property="og:type" content="article">\n  <meta property="og:url" content="https://jeffthomasiii.github.io/dictionary-of-the-ai-era/terms/{slug}/">\n  <meta name="twitter:card" content="summary">\n  <meta name="twitter:title" content="{esc(n)} | EpochLex">\n  <meta name="twitter:description" content="{esc(d,quote=True)}">\n  <script type="application/ld+json">{ld}</script>\n  <script>\n    (() => {{\n      try {{\n        const saved = localStorage.getItem("ai-era-theme");\n        const systemDark = window.matchMedia("(prefers-color-scheme: dark)").matches;\n        document.documentElement.dataset.theme = saved || (systemDark ? "dark" : "light");\n      }} catch (_) {{ document.documentElement.dataset.theme = "light"; }}\n    }})();\n  </script>\n  <link rel="stylesheet" href="../../assets/css/styles.css">\n  <link rel="stylesheet" href="../../assets/css/term-pages.css">\n  <link rel="stylesheet" href="../../assets/css/brand-theme.css">\n</head>\n<body>\n  <header class="site-header">\n    <div class="shell header-inner">\n      <a class="brand" href="../../" aria-label="EpochLex home"><span class="brand-lockup" aria-hidden="true"><img class="brand-lockup-image brand-lockup-light" src="../../assets/brand/epochlex/epochlex-logo-horizontal-light.png" alt=""><img class="brand-lockup-image brand-lockup-dark" src="../../assets/brand/epochlex/epochlex-logo-horizontal-dark.png" alt=""></span><span class="sr-only">EpochLex</span></a>\n      <nav class="primary-nav" aria-label="Primary navigation">\n        <a class="active" href="../../">Browse</a><a href="../../categories.html">Categories</a><a href="../../about.html">About</a><a href="../../contribute.html">Contribute</a><a href="../../methodology.html">Methodology</a>\n      </nav>\n      <button id="theme-toggle" class="theme-toggle" type="button" aria-label="Switch color theme" title="Switch color theme"><span class="sun" aria-hidden="true">☼</span><span class="toggle-track"><span class="toggle-knob"></span></span><span class="moon" aria-hidden="true">☾</span></button>\n    </div>\n  </header>\n\n  <main id="term-page" class="term-page shell" data-term-slug="{slug}">\n    <div id="term-fallback" class="term-fallback">\n      <nav class="term-breadcrumb" aria-label="Breadcrumb"><a href="../../">Browse</a><span aria-hidden="true">/</span><span>{esc(n)}</span></nav>\n      <p class="eyebrow">EpochLex entry</p>\n      <h1>{esc(n)}</h1>\n      <p class="fallback-pronunciation">{esc(p)}</p>\n      <p class="fallback-definition">{esc(d)}</p>\n    </div>\n  </main>\n\n  <footer class="site-footer"><div class="shell footer-inner"><span class="footer-mark" aria-hidden="true">◎</span><p><strong>EpochLex · Dictionary of the AI Era</strong><br>Vibe coded · Human-directed · AI-assisted · Human-reviewed</p><p class="footer-license">Code: MIT · Content: CC BY 4.0</p></div></footer>\n  <script src="../../assets/js/app.js"></script>\n  <script src="../../assets/js/term-page.js"></script>\n</body>\n</html>\n'''
for t in new_terms:
 p=root/'terms'/t['slug']/'index.html'; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(page(t))
xml=sitemap_path.read_text(); marker='</urlset>'
for t in new_terms:
 u=f"  <url>\n    <loc>https://jeffthomasiii.github.io/dictionary-of-the-ai-era/terms/{t['slug']}/</loc>\n  </url>\n"
 if u not in xml: xml=xml.replace(marker,u+marker)
sitemap_path.write_text(xml)
# validate
terms2=json.loads(terms_path.read_text()); prov2=json.loads(prov_path.read_text()); assert len(terms2)==122
slugs={x['slug'] for x in terms2}; assert slugs==set(prov2)
for s,v in prov2.items():
 for r in v.get('relatedTerms',[]): assert r in slugs and r!=s,(s,r)
for t in new_terms: assert (root/'terms'/t['slug']/'index.html').exists()
ET.parse(sitemap_path)
print('validated',len(terms2))
